        counts = {}
        for row in panel:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        return max(counts, key=counts.get)

    lb, rb = background(left), background(right)
    # The sparse, non-background cells are the marks; overlapping marks
    # become 3. Keep the left mark color as the output's background.
    left_marks = {v for row in left for v in row if v != lb}
    right_marks = {v for row in right for v in row if v != rb}
    mark = next(iter(left_marks), next(iter(right_marks), 0))
    out = []
    for i in range(h):
        row = []
        for j in range(n):
            if left[i][j] != lb and right[i][j] != rb:
                row.append(3)
            else:
                row.append(mark)
        out.append(row)
    return out
